// LLM Spend Guard: the policy engine.
//
// Zero dependencies and no I/O, so the same file runs inside the proxy
// (proxy.mjs), wrapped around an SDK call in your own code, in a test, and in
// the browser simulator (index.html).
//
// The shape is reserve-then-settle, the way a card hold works:
//
//   const g = createGuard(policy);
//   const d = g.check({ model, maxOutputTokens, input, scope: { user, feature, run } });
//   if (!d.allowed) return refuse(d.reasons);          // nothing was sent
//   const res = await callProvider({ ...body, max_tokens: d.maxOutputTokens });
//   g.settle(d.id, usageFrom(res));                    // actual cost replaces the hold
//
// `check` prices the worst case of the call (its input estimate plus the full
// output cap) and refuses it when that would cross a budget, so concurrent
// calls cannot all slip under the same remaining dollar. A call that is never
// settled is charged at its hold when the hold expires: an unknown outcome
// counts as spent, never as free.
//
// Budgets are fixed UTC calendar windows (the minute, hour, day or month a
// call starts in, or `total`), matching how providers bill. Breakers watch a
// rolling 60-second window for runaway loops: call rate, spend rate, and the
// same request repeated. Budget counters live in the store you pass (memory by
// default, a JSON file in store-file.mjs); breaker history is process-local.

export const WINDOWS = Object.freeze(['minute', 'hour', 'day', 'month', 'total']);
export const SCOPES = Object.freeze(['global', 'user', 'feature', 'key', 'run']);
const HOLD_TTL_SEC = 600;

export class GuardPolicyError extends Error {
  constructor(message) {
    super(message);
    this.name = 'GuardPolicyError';
  }
}

const isNum = (v) => typeof v === 'number' && Number.isFinite(v) && v >= 0;

function checkPrice(where, p) {
  if (!p || typeof p !== 'object') throw new GuardPolicyError(`${where}: price must be an object like {"in": 3, "out": 15}`);
  for (const k of ['in', 'out']) if (!isNum(p[k])) throw new GuardPolicyError(`${where}.${k}: USD per million tokens, a number >= 0`);
  for (const k of ['cacheRead', 'cacheWrite']) {
    if (p[k] !== undefined && !isNum(p[k])) throw new GuardPolicyError(`${where}.${k}: a number >= 0 when set`);
  }
  return { in: p.in, out: p.out, cacheRead: p.cacheRead ?? p.in, cacheWrite: p.cacheWrite ?? p.in };
}

/** Validate a policy and fill defaults. Throws GuardPolicyError naming the bad field. */
export function normalisePolicy(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new GuardPolicyError('policy must be a JSON object');
  const mode = raw.mode ?? 'enforce';
  if (!['enforce', 'observe'].includes(mode)) throw new GuardPolicyError('mode: "enforce" or "observe"');

  const prices = {};
  for (const [model, p] of Object.entries(raw.prices ?? {})) {
    if (model.startsWith('_')) continue; // "_note"-style comments in a JSON file
    prices[model] = checkPrice(`prices.${model}`, p);
  }
  const fallbackPrice = raw.fallbackPrice == null ? null : checkPrice('fallbackPrice', raw.fallbackPrice);

  for (const k of ['defaultMaxOutputTokens', 'maxOutputTokens']) {
    if (raw[k] != null && !(Number.isInteger(raw[k]) && raw[k] > 0)) throw new GuardPolicyError(`${k}: a whole number > 0`);
  }
  if (raw.maxCostPerCallUsd != null && !isNum(raw.maxCostPerCallUsd)) throw new GuardPolicyError('maxCostPerCallUsd: a number >= 0');

  const ids = new Set();
  const budgets = (raw.budgets ?? []).map((b, i) => {
    const where = `budgets[${i}]`;
    if (!b || typeof b !== 'object') throw new GuardPolicyError(`${where}: must be an object`);
    const id = b.id ?? `${b.scope ?? 'global'}-${b.window ?? 'day'}`;
    if (ids.has(id)) throw new GuardPolicyError(`${where}: duplicate id "${id}"`);
    ids.add(id);
    const scope = b.scope ?? 'global';
    const window = b.window ?? 'day';
    if (!SCOPES.includes(scope)) throw new GuardPolicyError(`${where}.scope: one of ${SCOPES.join(', ')}`);
    if (!WINDOWS.includes(window)) throw new GuardPolicyError(`${where}.window: one of ${WINDOWS.join(', ')}`);
    if (b.limitUsd == null && b.limitCalls == null) throw new GuardPolicyError(`${where}: set limitUsd, limitCalls, or both`);
    if (b.limitUsd != null && !isNum(b.limitUsd)) throw new GuardPolicyError(`${where}.limitUsd: a number >= 0`);
    if (b.limitCalls != null && !(Number.isInteger(b.limitCalls) && b.limitCalls >= 0)) throw new GuardPolicyError(`${where}.limitCalls: a whole number >= 0`);
    const alertAt = (b.alertAt ?? [0.5, 0.8, 1]).map(Number);
    if (alertAt.some((a) => !(a > 0 && a <= 1))) throw new GuardPolicyError(`${where}.alertAt: fractions in (0, 1]`);
    return { id, scope, window, limitUsd: b.limitUsd ?? null, limitCalls: b.limitCalls ?? null, alertAt: [...new Set(alertAt)].sort() };
  });

  const breakers = (raw.breakers ?? []).map((b, i) => {
    const where = `breakers[${i}]`;
    if (!b || typeof b !== 'object') throw new GuardPolicyError(`${where}: must be an object`);
    const scope = b.scope ?? 'global';
    if (!SCOPES.includes(scope)) throw new GuardPolicyError(`${where}.scope: one of ${SCOPES.join(', ')}`);
    const out = {
      id: b.id ?? `breaker-${scope}-${i}`,
      scope,
      maxCallsPerMinute: b.maxCallsPerMinute ?? null,
      maxSpendPerMinuteUsd: b.maxSpendPerMinuteUsd ?? null,
      maxRepeats: b.maxRepeats ?? null,
      repeatWindowSec: b.repeatWindowSec ?? 300,
      cooldownSec: b.cooldownSec ?? 300,
    };
    if (out.maxCallsPerMinute == null && out.maxSpendPerMinuteUsd == null && out.maxRepeats == null) {
      throw new GuardPolicyError(`${where}: set maxCallsPerMinute, maxSpendPerMinuteUsd or maxRepeats`);
    }
    for (const k of ['maxCallsPerMinute', 'maxRepeats']) {
      if (out[k] != null && !(Number.isInteger(out[k]) && out[k] > 0)) throw new GuardPolicyError(`${where}.${k}: a whole number > 0`);
    }
    for (const k of ['maxSpendPerMinuteUsd', 'repeatWindowSec', 'cooldownSec']) {
      if (!(out[k] == null || isNum(out[k]))) throw new GuardPolicyError(`${where}.${k}: a number >= 0`);
    }
    return out;
  });

  return {
    mode,
    prices,
    fallbackPrice,
    requireKnownPrice: raw.requireKnownPrice ?? true,
    requireOutputCap: raw.requireOutputCap ?? true,
    defaultMaxOutputTokens: raw.defaultMaxOutputTokens ?? null,
    maxOutputTokens: raw.maxOutputTokens ?? null,
    maxCostPerCallUsd: raw.maxCostPerCallUsd ?? null,
    holdTtlSec: raw.holdTtlSec ?? HOLD_TTL_SEC,
    budgets,
    breakers,
  };
}

/** The calendar bucket a timestamp falls in, in UTC. */
export function windowKey(window, t) {
  if (window === 'total') return 'all';
  const iso = new Date(t).toISOString(); // 2026-10-16T09:41:07.123Z
  return { month: iso.slice(0, 7), day: iso.slice(0, 10), hour: iso.slice(0, 13), minute: iso.slice(0, 16) }[window];
}

/** When the bucket containing t ends, in ms; Infinity for `total`. */
export function windowEnd(window, t) {
  const d = new Date(t);
  if (window === 'total') return Infinity;
  if (window === 'month') return Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1);
  const ms = { day: 86_400_000, hour: 3_600_000, minute: 60_000 }[window];
  return Math.floor(t / ms) * ms + ms;
}

/**
 * Price for a model: exact name first, then the longest configured prefix, so
 * "claude-sonnet-4-5" also prices a dated snapshot like "claude-sonnet-4-5-20250929".
 */
export function priceFor(policy, model) {
  if (typeof model !== 'string' || !model) return policy.fallbackPrice;
  if (policy.prices[model]) return policy.prices[model];
  let best = null;
  for (const name of Object.keys(policy.prices)) {
    if (model.startsWith(name) && (!best || name.length > best.length)) best = name;
  }
  return best ? policy.prices[best] : policy.fallbackPrice;
}

/** USD for a usage record { input, output, cacheRead, cacheWrite } (token counts). */
export function costUsd(price, usage = {}) {
  const n = (v) => (Number.isFinite(v) && v > 0 ? v : 0);
  return (n(usage.input) * price.in + n(usage.output) * price.out
    + n(usage.cacheRead) * price.cacheRead + n(usage.cacheWrite) * price.cacheWrite) / 1e6;
}

/**
 * A deliberately high input-token estimate: UTF-8 bytes / 3 of the JSON the
 * request sends. Real tokenisers average nearer 4 bytes per token for English,
 * so the hold errs toward refusing a call that would just fit, never toward
 * letting one through that would not.
 */
export function estimateInputTokens(input) {
  if (input == null) return 0;
  const text = typeof input === 'string' ? input : JSON.stringify(input);
  return Math.ceil(new TextEncoder().encode(text).length / 3);
}

/** FNV-1a over a string, as 8 hex characters: a cheap repeat fingerprint. */
export function fingerprint(text) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

export function memoryStore(initial = {}) {
  const m = new Map(Object.entries(initial));
  return {
    get: (k) => m.get(k),
    set: (k, v) => { m.set(k, v); },
    delete: (k) => { m.delete(k); },
    entries: () => [...m.entries()],
  };
}

const scopeValue = (scope, ctx) => (scope === 'global' ? '*' : String(ctx?.[scope] ?? '(none)'));
const round6 = (x) => Math.round(x * 1e6) / 1e6;

export function createGuard(rawPolicy, { store = memoryStore(), now = () => Date.now(), onEvent = () => {} } = {}) {
  const policy = normalisePolicy(rawPolicy);
  const holds = new Map();
  const history = new Map(); // breaker id + scope value -> [{ t, usd, fp, holdId }]
  let halted = null;
  let seq = 0;

  const emit = (event) => {
    try { onEvent({ at: new Date(now()).toISOString(), ...event }); } catch { /* a notifier must never break the guard */ }
  };

  const bucketKey = (b, ctx, t) => `b|${b.id}|${scopeValue(b.scope, ctx)}|${windowKey(b.window, t)}`;
  const readBucket = (k) => store.get(k) ?? { spent: 0, reserved: 0, calls: 0 };

  function expireHolds(t) {
    for (const [id, h] of holds) if (t - h.t > policy.holdTtlSec * 1000) settle(id, null, { reason: 'hold-expired' });
  }

  function pruneHistory(t) {
    for (const [k, list] of history) {
      const keep = list.filter((e) => t - e.t <= Math.max(60, e.repeatWindowSec) * 1000);
      if (keep.length) history.set(k, keep); else history.delete(k);
    }
  }

  function breakerVerdict(br, ctx, t, est, fp) {
    const sv = scopeValue(br.scope, ctx);
    const tripKey = `trip|${br.id}|${sv}`;
    const trip = store.get(tripKey);
    if (trip && trip.until > t) {
      return { code: 'breaker-open', breaker: br.id, scopeValue: sv, retryAfterSec: Math.ceil((trip.until - t) / 1000), message: `breaker ${br.id} is open for ${br.scope}=${sv} (${trip.reason}); retry in ${Math.ceil((trip.until - t) / 1000)}s` };
    }
    const list = history.get(`${br.id}|${sv}`) ?? [];
    const lastMinute = list.filter((e) => t - e.t < 60_000);
    let reason = null;
    if (br.maxCallsPerMinute != null && lastMinute.length + 1 > br.maxCallsPerMinute) {
      reason = `more than ${br.maxCallsPerMinute} calls in 60s`;
    } else if (br.maxSpendPerMinuteUsd != null && lastMinute.reduce((s, e) => s + e.usd, 0) + est > br.maxSpendPerMinuteUsd) {
      reason = `more than $${br.maxSpendPerMinuteUsd} in 60s`;
    } else if (br.maxRepeats != null && list.filter((e) => e.fp === fp && t - e.t < br.repeatWindowSec * 1000).length + 1 > br.maxRepeats) {
      reason = `the same request more than ${br.maxRepeats} times in ${br.repeatWindowSec}s`;
    }
    if (!reason) return null;
    const until = t + br.cooldownSec * 1000;
    if (policy.mode === 'enforce') store.set(tripKey, { until, reason, at: t });
    emit({ type: 'trip', breaker: br.id, scope: br.scope, scopeValue: sv, reason, cooldownSec: br.cooldownSec, mode: policy.mode });
    return { code: 'breaker-tripped', breaker: br.id, scopeValue: sv, retryAfterSec: br.cooldownSec, message: `breaker ${br.id} tripped for ${br.scope}=${sv}: ${reason}` };
  }

  /**
   * Decide on a call before it is sent.
   *   req: { model, maxOutputTokens?, input? | inputTokens?, scope?: { user, feature, key, run }, fingerprint? }
   * Returns { allowed, id, mode, estimateUsd, maxOutputTokens, inputTokens, reasons[], warnings[] }.
   * In observe mode `allowed` is always true and `reasons` says what enforce would have refused.
   */
  function check(req = {}) {
    const t = now();
    expireHolds(t);
    pruneHistory(t);
    const ctx = req.scope ?? {};
    const reasons = [];
    const warnings = [];
    const price = priceFor(policy, req.model);

    if (halted) reasons.push({ code: 'halted', message: `all calls are halted: ${halted}` });
    if (!price && policy.requireKnownPrice) {
      reasons.push({ code: 'unpriced-model', message: `no price configured for model "${req.model}"; add it to prices or set fallbackPrice` });
    }

    let maxOut = Number.isInteger(req.maxOutputTokens) && req.maxOutputTokens > 0 ? req.maxOutputTokens : null;
    if (maxOut == null) {
      if (policy.defaultMaxOutputTokens) {
        maxOut = policy.defaultMaxOutputTokens;
        warnings.push({ code: 'output-cap-added', message: `no output cap on the request; added ${maxOut}` });
      } else if (policy.requireOutputCap) {
        reasons.push({ code: 'no-output-cap', message: 'the request sets no output-token cap, so its cost has no upper bound' });
      }
    }
    if (maxOut != null && policy.maxOutputTokens && maxOut > policy.maxOutputTokens) {
      warnings.push({ code: 'output-cap-clamped', message: `output cap ${maxOut} lowered to the policy ceiling ${policy.maxOutputTokens}` });
      maxOut = policy.maxOutputTokens;
    }

    const inputTokens = Number.isFinite(req.inputTokens) ? req.inputTokens : estimateInputTokens(req.input);
    const estimateUsd = price ? costUsd(price, { input: inputTokens, output: maxOut ?? 0 }) : 0;
    if (policy.maxCostPerCallUsd != null && estimateUsd > policy.maxCostPerCallUsd) {
      reasons.push({ code: 'call-too-expensive', message: `worst case $${estimateUsd.toFixed(4)} is over the per-call limit $${policy.maxCostPerCallUsd}` });
    }

    const fp = req.fingerprint ?? fingerprint(`${req.model}|${typeof req.input === 'string' ? req.input : JSON.stringify(req.input ?? '')}`);
    if (!reasons.length) {
      for (const br of policy.breakers) {
        const v = breakerVerdict(br, ctx, t, estimateUsd, fp);
        if (v) reasons.push(v);
      }
    }

    const keys = [];
    for (const b of policy.budgets) {
      const k = bucketKey(b, ctx, t);
      keys.push([b, k]);
      const cur = readBucket(k);
      const sv = scopeValue(b.scope, ctx);
      if (b.limitUsd != null && cur.spent + cur.reserved + estimateUsd > b.limitUsd + 1e-12) {
        reasons.push({
          code: 'budget-exceeded', budget: b.id, scopeValue: sv,
          retryAfterSec: Number.isFinite(windowEnd(b.window, t)) ? Math.ceil((windowEnd(b.window, t) - t) / 1000) : null,
          message: `budget ${b.id} (${b.scope}=${sv}, ${b.window}): $${round6(cur.spent + cur.reserved)} used or held of $${b.limitUsd}; this call could cost up to $${estimateUsd.toFixed(4)}`,
        });
      }
      if (b.limitCalls != null && cur.calls + 1 > b.limitCalls) {
        reasons.push({
          code: 'call-limit', budget: b.id, scopeValue: sv,
          retryAfterSec: Number.isFinite(windowEnd(b.window, t)) ? Math.ceil((windowEnd(b.window, t) - t) / 1000) : null,
          message: `budget ${b.id} (${b.scope}=${sv}, ${b.window}): ${cur.calls} of ${b.limitCalls} calls used`,
        });
      }
    }

    const enforce = policy.mode === 'enforce';
    const allowed = !enforce || reasons.length === 0;
    const decision = { allowed, id: null, mode: policy.mode, model: req.model ?? null, estimateUsd: round6(estimateUsd), maxOutputTokens: maxOut, inputTokens, reasons, warnings };
    if (reasons.length) emit({ type: enforce ? 'block' : 'would-block', model: req.model ?? null, scope: ctx, reasons });
    if (!allowed) return decision;

    const id = `h${++seq}-${t.toString(36)}`;
    for (const [, k] of keys) {
      const cur = readBucket(k);
      store.set(k, { ...cur, reserved: cur.reserved + estimateUsd, calls: cur.calls + 1 });
    }
    const entries = [];
    for (const br of policy.breakers) {
      const hk = `${br.id}|${scopeValue(br.scope, ctx)}`;
      const e = { t, usd: estimateUsd, fp, holdId: id, repeatWindowSec: br.repeatWindowSec };
      history.set(hk, [...(history.get(hk) ?? []), e]);
      entries.push(e);
    }
    holds.set(id, { t, price, estimateUsd, keys, entries, ctx });
    decision.id = id;
    return decision;
  }

  function maybeAlert(b, k, before, after, ctx) {
    if (b.limitUsd == null || b.limitUsd === 0) return;
    for (const a of b.alertAt) {
      const line = a * b.limitUsd;
      if (before < line - 1e-12 && after >= line - 1e-12) {
        const ak = `a|${k}|${a}`;
        if (store.get(ak)) continue;
        store.set(ak, true);
        emit({ type: 'alert', budget: b.id, scope: b.scope, scopeValue: scopeValue(b.scope, ctx), window: b.window, threshold: a, spentUsd: round6(after), limitUsd: b.limitUsd });
      }
    }
  }

  /**
   * Replace a hold with the call's actual cost. `usage` is { input, output,
   * cacheRead, cacheWrite } in tokens, or null when the outcome is unknown
   * (the stream broke, the provider sent no usage): the hold is then charged.
   */
  function settle(id, usage, { reason } = {}) {
    const h = holds.get(id);
    if (!h) return null;
    holds.delete(id);
    const actual = usage && h.price ? costUsd(h.price, usage) : h.estimateUsd;
    for (const [b, k] of h.keys) {
      const cur = readBucket(k);
      const next = { ...cur, reserved: Math.max(0, cur.reserved - h.estimateUsd), spent: cur.spent + actual };
      store.set(k, next);
      maybeAlert(b, k, cur.spent, next.spent, h.ctx);
    }
    for (const e of h.entries) e.usd = actual;
    emit({ type: 'settle', id, costUsd: round6(actual), heldUsd: round6(h.estimateUsd), reason: reason ?? (usage ? 'usage' : 'unknown-usage') });
    return { costUsd: round6(actual), heldUsd: round6(h.estimateUsd) };
  }

  /** Release a hold without charging it: the call never reached the provider, or the provider refused it. */
  function cancel(id) {
    const h = holds.get(id);
    if (!h) return false;
    holds.delete(id);
    for (const [, k] of h.keys) {
      const cur = readBucket(k);
      store.set(k, { ...cur, reserved: Math.max(0, cur.reserved - h.estimateUsd), calls: Math.max(0, cur.calls - 1) });
    }
    for (const [hk, list] of history) history.set(hk, list.filter((e) => e.holdId !== id));
    return true;
  }

  /** Current window of every budget bucket the store holds, open breakers, and the halt flag. */
  function status() {
    const t = now();
    expireHolds(t);
    const budgets = [];
    const open = [];
    for (const [k, v] of store.entries()) {
      const parts = k.split('|');
      if (parts[0] === 'b') {
        const b = policy.budgets.find((x) => x.id === parts[1]);
        if (!b || windowKey(b.window, t) !== parts[3]) continue;
        budgets.push({ budget: b.id, scope: b.scope, scopeValue: parts[2], window: b.window, windowKey: parts[3], spentUsd: round6(v.spent), heldUsd: round6(v.reserved), limitUsd: b.limitUsd, calls: v.calls, limitCalls: b.limitCalls });
      } else if (parts[0] === 'trip' && v.until > t) {
        open.push({ breaker: parts[1], scopeValue: parts[2], reason: v.reason, retryAfterSec: Math.ceil((v.until - t) / 1000) });
      }
    }
    return { mode: policy.mode, halted, holds: holds.size, budgets, openBreakers: open };
  }

  /** Drop counters for windows that have closed, so a long-lived store stays small. */
  function compact() {
    const t = now();
    let dropped = 0;
    for (const [k] of store.entries()) {
      const parts = k.split('|');
      const bk = parts[0] === 'a' ? parts.slice(1) : parts;
      if (bk[0] !== 'b') {
        if (parts[0] === 'trip' && store.get(k).until <= t) { store.delete(k); dropped++; }
        continue;
      }
      const b = policy.budgets.find((x) => x.id === bk[1]);
      if (!b || windowKey(b.window, t) !== bk[3]) { store.delete(k); dropped++; }
    }
    return dropped;
  }

  return {
    policy,
    check,
    settle,
    cancel,
    status,
    compact,
    halt(reason = 'halted by operator') { halted = String(reason); emit({ type: 'halt', reason: halted }); },
    resume() { halted = null; emit({ type: 'resume' }); },
    /** check, run, settle in one go. `run(decision)` resolves to { result, usage }. */
    async guarded(req, run) {
      const d = check(req);
      if (!d.allowed) {
        const err = new Error(d.reasons.map((r) => r.message).join('; '));
        err.name = 'SpendGuardBlocked';
        err.decision = d;
        throw err;
      }
      let out;
      try {
        out = await run(d);
      } catch (e) {
        if (d.id) (e?.charged ? settle(d.id, null) : cancel(d.id));
        throw e;
      }
      if (d.id) settle(d.id, out?.usage ?? null);
      return out?.result;
    },
  };
}

providers.mjs.text:
// What the guard needs from each provider's wire format: the model, the
// output cap, the input to estimate, and the usage the response reports
// (whole JSON or a server-sent-event stream). Pure functions, no I/O.

export const PROVIDERS = Object.freeze({
  anthropic: {
    path: '/v1/messages',
    defaultBaseUrl: 'https://api.anthropic.com',
    capField: 'max_tokens',
  },
  openai: {
    path: '/v1/chat/completions',
    defaultBaseUrl: 'https://api.openai.com',
    capField: 'max_completion_tokens',
  },
});

/** Pull { model, maxOutputTokens, input, stream } out of a request body. */
export function describeRequest(provider, body) {
  const b = body && typeof body === 'object' ? body : {};
  if (provider === 'anthropic') {
    return {
      model: b.model,
      maxOutputTokens: b.max_tokens,
      input: { system: b.system, messages: b.messages, tools: b.tools },
      stream: b.stream === true,
    };
  }
  return {
    model: b.model,
    // max_tokens is the older name; when both are sent the newer one wins upstream.
    maxOutputTokens: b.max_completion_tokens ?? b.max_tokens,
    input: { messages: b.messages, tools: b.tools },
    stream: b.stream === true,
  };
}

/**
 * The body to forward: the guard's output cap written in, and on an OpenAI
 * stream `include_usage` switched on so the final chunk reports what was used.
 */
export function rewriteRequest(provider, body, maxOutputTokens) {
  const out = { ...body };
  if (maxOutputTokens != null) {
    if (provider === 'anthropic') out.max_tokens = maxOutputTokens;
    else {
      if ('max_tokens' in out && !('max_completion_tokens' in out)) out.max_tokens = maxOutputTokens;
      else out.max_completion_tokens = maxOutputTokens;
    }
  }
  if (provider === 'openai' && out.stream === true) {
    out.stream_options = { ...(out.stream_options ?? {}), include_usage: true };
  }
  return out;
}

/** Usage from a non-streamed response, as { input, output, cacheRead, cacheWrite }, or null. */
export function usageFromResponse(provider, data) {
  const u = data?.usage;
  if (!u || typeof u !== 'object') return null;
  if (provider === 'anthropic') {
    return {
      input: u.input_tokens ?? 0,
      output: u.output_tokens ?? 0,
      cacheRead: u.cache_read_input_tokens ?? 0,
      cacheWrite: u.cache_creation_input_tokens ?? 0,
    };
  }
  // OpenAI's prompt_tokens includes the cached part; split it out so cached
  // tokens are priced at the cache rate, not twice.
  const prompt = u.prompt_tokens ?? u.input_tokens ?? 0;
  const cached = u.prompt_tokens_details?.cached_tokens ?? u.input_tokens_details?.cached_tokens ?? 0;
  return {
    input: Math.max(0, prompt - cached),
    output: u.completion_tokens ?? u.output_tokens ?? 0,
    cacheRead: cached,
    cacheWrite: 0,
  };
}

/**
 * Incremental SSE reader that accumulates usage while the bytes pass through
 * untouched. Feed it text chunks with push(); usage() is null until the stream
 * has reported any.
 *   Anthropic: message_start carries input and cache counts, message_delta the
 *   running output count. OpenAI: the last chunk carries `usage` when
 *   stream_options.include_usage is on.
 */
export function streamUsageReader(provider) {
  let buf = '';
  let usage = null;
  const onData = (json) => {
    let ev;
    try { ev = JSON.parse(json); } catch { return; }
    if (provider === 'anthropic') {
      if (ev.type === 'message_start' && ev.message?.usage) {
        usage = { ...(usage ?? { output: 0 }), ...usageFromResponse('anthropic', ev.message) };
      } else if (ev.type === 'message_delta' && ev.usage) {
        usage = { input: 0, cacheRead: 0, cacheWrite: 0, ...(usage ?? {}), output: ev.usage.output_tokens ?? usage?.output ?? 0 };
      }
    } else if (ev.usage) {
      usage = usageFromResponse('openai', ev);
    }
  };
  return {
    push(text) {
      buf += text;
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, nl).replace(/\r$/, '');
        buf = buf.slice(nl + 1);
        if (line.startsWith('data:')) {
          const payload = line.slice(5).trim();
          if (payload && payload !== '[DONE]') onData(payload);
        }
      }
    },
    usage: () => usage,
  };
}

/** A refusal body in the provider's own error shape, so its SDK raises a normal API error. */
export function blockedBody(provider, decision) {
  const message = `LLM Spend Guard refused this call: ${decision.reasons.map((r) => r.message).join('; ')}`;
  const code = decision.reasons[0]?.code ?? 'blocked';
  if (provider === 'anthropic') return { type: 'error', error: { type: 'spend_guard_blocked', code, message } };
  return { error: { message, type: 'spend_guard_blocked', code, param: null } };
}

proxy.mjs.text:
// The self-hosted proxy: point an SDK's base URL here and every call passes
// the guard before it reaches the provider.
//
//   ANTHROPIC_BASE_URL=http://127.0.0.1:8787/anthropic
//   OPENAI_BASE_URL=http://127.0.0.1:8787/openai/v1
//
// Scope comes from request headers: x-guard-user, x-guard-feature, x-guard-run.
// The `key` scope is a fingerprint of the caller's credential, never the
// credential itself. Refusals use the provider's own error shape: HTTP 402
// when a budget is spent (SDKs do not retry it), 429 with Retry-After when a
// breaker is open (the wait is real).
//
// Keys: if the deployer sets an upstream key, callers must present one of
// GUARD_PROXY_TOKENS, or anyone who can reach the port spends the deployer's
// money. With no upstream key the caller's own key is forwarded untouched.

import { createServer } from 'node:http';
import { fingerprint } from './guard.mjs';
import { PROVIDERS, blockedBody, describeRequest, rewriteRequest, streamUsageReader, usageFromResponse } from './providers.mjs';

const MAX_BODY = 20 * 1024 * 1024;
// Hop-by-hop and length headers are the server's to set; the rest of the
// upstream response (request ids, rate-limit headers) is passed through.
const DROP_RESPONSE_HEADERS = new Set(['connection', 'keep-alive', 'transfer-encoding', 'content-length', 'content-encoding']);

function send(res, status, body, headers = {}) {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text), ...headers });
  res.end(text);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > MAX_BODY) { reject(Object.assign(new Error('request body too large'), { status: 413 })); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function bearer(req) {
  const h = req.headers.authorization ?? '';
  return h.toLowerCase().startsWith('bearer ') ? h.slice(7).trim() : null;
}

function route(pathname) {
  // /anthropic/v1/messages, /openai/v1/chat/completions, or the bare provider path.
  for (const [name, p] of Object.entries(PROVIDERS)) {
    if (pathname === `/${name}${p.path}` || pathname === p.path) return name;
  }
  return null;
}

/**
 * Build the request handler. `upstreams[provider]` is { baseUrl?, apiKey? }.
 * `proxyTokens` is the list callers must present when an upstream key is set.
 */
export function createHandler({ guard, upstreams = {}, proxyTokens = [], adminToken = null, fetch: fetchImpl = globalThis.fetch, log = () => {} }) {
  const tokens = new Set(proxyTokens.filter(Boolean));

  async function admin(req, res, url) {
    if (!adminToken || bearer(req) !== adminToken) return send(res, 401, { error: 'set GUARD_ADMIN_TOKEN and send it as a bearer token' });
    if (req.method === 'GET' && url.pathname === '/guard/status') return send(res, 200, guard.status());
    if (req.method === 'POST' && url.pathname === '/guard/halt') {
      guard.halt(url.searchParams.get('reason') || 'halted by operator');
      return send(res, 200, guard.status());
    }
    if (req.method === 'POST' && url.pathname === '/guard/resume') { guard.resume(); return send(res, 200, guard.status()); }
    return send(res, 404, { error: 'not found' });
  }

  return async function handle(req, res) {
    const url = new URL(req.url, 'http://proxy.local');
    if (url.pathname === '/healthz') return send(res, 200, { ok: true });
    if (url.pathname.startsWith('/guard/')) return admin(req, res, url);

    const provider = route(url.pathname);
    if (!provider || req.method !== 'POST') return send(res, 404, { error: `no route for ${req.method} ${url.pathname}` });
    const up = upstreams[provider] ?? {};

    // Who is calling, and with what credential.
    const callerKey = provider === 'anthropic' ? (req.headers['x-api-key'] ?? bearer(req)) : bearer(req);
    const guardToken = req.headers['x-guard-token'] ?? (up.apiKey ? callerKey : null);
    if (up.apiKey && !tokens.has(guardToken)) {
      return send(res, 401, blockedBody(provider, { reasons: [{ code: 'unauthorised', message: 'this proxy holds its own key; send a GUARD_PROXY_TOKENS value as the API key or x-guard-token' }] }));
    }
    const upstreamKey = up.apiKey ?? callerKey;
    if (!upstreamKey) return send(res, 401, blockedBody(provider, { reasons: [{ code: 'no-key', message: 'no API key on the request and none configured upstream' }] }));

    let body;
    try {
      body = JSON.parse(await readBody(req));
    } catch (e) {
      return send(res, e.status ?? 400, { error: e.status ? e.message : 'request body is not JSON' });
    }

    const d0 = describeRequest(provider, body);
    const scope = {
      user: req.headers['x-guard-user'],
      feature: req.headers['x-guard-feature'],
      run: req.headers['x-guard-run'],
      key: fingerprint(String(guardToken ?? upstreamKey)),
    };
    const decision = guard.check({ model: d0.model, maxOutputTokens: d0.maxOutputTokens, input: d0.input, scope });
    if (!decision.allowed) {
      const breaker = decision.reasons.find((r) => r.code.startsWith('breaker'));
      const status = breaker ? 429 : 402;
      const retry = Math.max(0, ...decision.reasons.map((r) => r.retryAfterSec ?? 0));
      log({ type: 'refused', provider, model: d0.model, status, reasons: decision.reasons.map((r) => r.code) });
      return send(res, status, blockedBody(provider, decision), {
        'x-guard-blocked': decision.reasons.map((r) => r.code).join(','),
        ...(retry ? { 'retry-after': String(retry) } : {}),
      });
    }

    const headers = { 'content-type': 'application/json' };
    if (provider === 'anthropic') {
      headers['x-api-key'] = upstreamKey;
      headers['anthropic-version'] = req.headers['anthropic-version'] ?? '2023-06-01';
      if (req.headers['anthropic-beta']) headers['anthropic-beta'] = req.headers['anthropic-beta'];
    } else {
      headers.authorization = `Bearer ${upstreamKey}`;
      if (req.headers['openai-organization']) headers['openai-organization'] = req.headers['openai-organization'];
      if (req.headers['openai-project']) headers['openai-project'] = req.headers['openai-project'];
    }
    const base = (up.baseUrl ?? PROVIDERS[provider].defaultBaseUrl).replace(/\/+$/, '');
    const target = `${base}${PROVIDERS[provider].path}`;
    const forward = rewriteRequest(provider, body, decision.maxOutputTokens);

    let upstream;
    try {
      upstream = await fetchImpl(target, { method: 'POST', headers, body: JSON.stringify(forward) });
    } catch (e) {
      guard.cancel(decision.id);
      return send(res, 502, { error: `could not reach ${provider}: ${e.message}` });
    }

    const outHeaders = {};
    upstream.headers.forEach((v, k) => { if (!DROP_RESPONSE_HEADERS.has(k)) outHeaders[k] = v; });
    if (decision.warnings.length) outHeaders['x-guard-warnings'] = decision.warnings.map((w) => w.code).join(',');

    if (!upstream.ok) {
      // Providers do not bill a request they reject; release the hold.
      guard.cancel(decision.id);
      const text = await upstream.text();
      res.writeHead(upstream.status, outHeaders);
      return res.end(text);
    }

    const isStream = (upstream.headers.get('content-type') ?? '').includes('text/event-stream');
    if (!isStream) {
      const text = await upstream.text();
      let usage = null;
      try { usage = usageFromResponse(provider, JSON.parse(text)); } catch { /* charged at the hold */ }
      const settled = guard.settle(decision.id, usage);
      log({ type: 'settled', provider, model: d0.model, ...settled });
      res.writeHead(upstream.status, outHeaders);
      return res.end(text);
    }

    // Stream: pass every byte through as it arrives while reading usage off it.
    res.writeHead(upstream.status, outHeaders);
    const reader = streamUsageReader(provider);
    const decoder = new TextDecoder();
    let settled = false;
    let complete = false;
    // Usage read off a stream that ended early may undercount what the
    // provider bills for it, so an incomplete stream is charged at its hold.
    const finish = () => {
      if (settled) return;
      settled = true;
      const s = guard.settle(decision.id, complete ? reader.usage() : null);
      log({ type: 'settled', provider, model: d0.model, stream: true, complete, ...s });
    };
    res.on('close', finish);
    try {
      for await (const chunk of upstream.body) {
        if (res.destroyed) break;
        reader.push(decoder.decode(chunk, { stream: true }));
        if (!res.write(chunk)) await new Promise((r) => { res.once('drain', r); res.once('close', r); });
      }
      complete = !res.destroyed;
    } catch {
      /* the client or the provider went away; finish() charges the hold */
    }
    finish();
    res.end();
  };
}

/** Start an HTTP server. Refuses to expose a deployer-held key on a public interface without tokens. */
export function startProxy({ host = '127.0.0.1', port = 8787, ...opts }) {
  const holdsKey = Object.values(opts.upstreams ?? {}).some((u) => u?.apiKey);
  const local = host === '127.0.0.1' || host === 'localhost' || host === '::1';
  if (holdsKey && !local && !(opts.proxyTokens ?? []).filter(Boolean).length) {
    throw new Error(`refusing to listen on ${host} with an upstream API key and no GUARD_PROXY_TOKENS: anyone who reaches the port would spend your money`);
  }
  const handler = createHandler(opts);
  const server = createServer((req, res) => {
    handler(req, res).catch((e) => {
      if (!res.headersSent) send(res, 500, { error: 'proxy error' });
      else res.end();
      opts.log?.({ type: 'error', message: e.message });
    });
  });
  return new Promise((resolve) => server.listen(port, host, () => resolve(server)));
}

simulate.mjs.text:
// Replay a usage log through a policy: "would this guard have stopped that
// bill?" Each row is checked at its own timestamp with its real token counts
// (so the hold equals the actual cost) and settled if allowed. Pure; shared
// by the CLI and the browser page.

import { costUsd, createGuard, normalisePolicy, priceFor } from './guard.mjs';

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : 0;
};

function splitCsvLine(line) {
  const out = [];
  let cur = '';
  let q = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (q) {
      if (c === '"' && line[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c;
    } else if (c === '"') q = true;
    else if (c === ',') { out.push(cur); cur = ''; } else cur += c;
  }
  out.push(cur);
  return out;
}

/** Rows from JSONL, a JSON array, or CSV with a header line. */
export function parseLog(text) {
  const t = String(text ?? '').trim();
  if (!t) return [];
  if (t.startsWith('[')) return JSON.parse(t);
  if (t.startsWith('{')) {
    return t.split(/\r?\n/).filter((l) => l.trim()).map((l, i) => {
      try { return JSON.parse(l); } catch { throw new Error(`line ${i + 1} is not JSON`); }
    });
  }
  const lines = t.split(/\r?\n/).filter((l) => l.trim());
  const head = splitCsvLine(lines[0]).map((h) => h.trim());
  return lines.slice(1).map((l) => Object.fromEntries(splitCsvLine(l).map((v, i) => [head[i], v])));
}

/** One row as { t, model, usage, scope }, accepting Anthropic- and OpenAI-style fields, nested or flat. */
export function normaliseRow(row, i) {
  const u = row.usage && typeof row.usage === 'object' ? row.usage : row;
  const ts = row.created_at ?? row.timestamp ?? row.time ?? row.ts;
  let t = typeof ts === 'number' ? (ts < 1e12 ? ts * 1000 : ts) : Date.parse(ts);
  if (!Number.isFinite(t)) t = null;
  let usage;
  if (u.prompt_tokens != null || u.completion_tokens != null || u.prompt_tokens_details) {
    const cached = num(u.prompt_tokens_details?.cached_tokens ?? u.cached_tokens);
    usage = { input: Math.max(0, num(u.prompt_tokens) - cached), output: num(u.completion_tokens), cacheRead: cached, cacheWrite: 0 };
  } else {
    usage = {
      input: num(u.input_tokens),
      output: num(u.output_tokens),
      cacheRead: num(u.cache_read_input_tokens ?? u.cache_read_tokens),
      cacheWrite: num(u.cache_creation_input_tokens ?? u.cache_write_tokens),
    };
  }
  return {
    index: i,
    t,
    model: row.model ?? null,
    usage,
    scope: {
      user: row.user ?? row.user_id ?? undefined,
      feature: row.feature ?? row.label ?? undefined,
      run: row.run ?? row.run_id ?? row.trace_id ?? row.session_id ?? undefined,
      key: row.key ?? row.api_key_id ?? undefined,
    },
    // Without a hash in the log every row is distinct: a replay cannot tell
    // two prompts apart from token counts, so it never invents a repeat.
    fingerprint: row.fingerprint ?? row.prompt_hash ?? `row-${i}`,
  };
}

/**
 * Replay rows through a policy. Rows without a timestamp are spaced one
 * second apart after the previous row, so order still drives the breakers.
 * Returns totals, the first refusals, and the end-of-replay budget state.
 */
export function simulate(rawPolicy, rawRows, { maxEvents = 200 } = {}) {
  const policy = normalisePolicy({ ...rawPolicy, mode: 'enforce' });
  const rows = rawRows.map(normaliseRow);
  let last = rows.find((r) => r.t != null)?.t ?? Date.UTC(2026, 0, 1);
  for (const r of rows) {
    if (r.t == null) r.t = last + 1000;
    last = r.t;
  }
  rows.sort((a, b) => a.t - b.t || a.index - b.index);

  let clock = rows[0]?.t ?? 0;
  const events = [];
  const guard = createGuard(policy, { now: () => clock, onEvent: (e) => { if (e.type === 'trip' || e.type === 'alert') events.push(e); } });

  const totals = { rows: rows.length, allowed: 0, blocked: 0, unpriced: 0, actualUsd: 0, allowedUsd: 0, blockedUsd: 0 };
  const byCode = {};
  const refusals = [];
  let firstBlock = null;

  for (const r of rows) {
    clock = r.t;
    const price = priceFor(policy, r.model);
    const actual = price ? costUsd(price, r.usage) : 0;
    if (!price) totals.unpriced++;
    totals.actualUsd += actual;
    const d = guard.check({
      model: r.model,
      // The replay knows the true counts, so the hold is the real cost.
      inputTokens: r.usage.input + r.usage.cacheRead + r.usage.cacheWrite,
      maxOutputTokens: r.usage.output > 0 ? r.usage.output : 1,
      scope: r.scope,
      fingerprint: r.fingerprint,
    });
    if (d.allowed) {
      guard.settle(d.id, r.usage);
      totals.allowed++;
      totals.allowedUsd += actual;
    } else {
      totals.blocked++;
      totals.blockedUsd += actual;
      for (const reason of d.reasons) byCode[reason.code] = (byCode[reason.code] ?? 0) + 1;
      if (!firstBlock) firstBlock = { row: r.index, at: new Date(r.t).toISOString(), reasons: d.reasons };
      if (refusals.length < maxEvents) refusals.push({ row: r.index, at: new Date(r.t).toISOString(), model: r.model, costUsd: actual, codes: d.reasons.map((x) => x.code), message: d.reasons[0].message });
    }
  }
  const round = (x) => Math.round(x * 1e4) / 1e4;
  for (const k of ['actualUsd', 'allowedUsd', 'blockedUsd']) totals[k] = round(totals[k]);
  return {
    totals,
    byCode,
    firstBlock,
    refusals,
    events: events.slice(0, maxEvents),
    span: rows.length ? { from: new Date(rows[0].t).toISOString(), to: new Date(rows[rows.length - 1].t).toISOString() } : null,
    end: guard.status(),
  };
}

/**
 * A synthetic runaway: an agent stuck re-sending the same request, plus
 * ordinary traffic. Labelled as made up wherever it is shown; it exists so the
 * page and the tests demonstrate a trip without anyone's real log.
 */
export function exampleRunawayLog({ start = Date.UTC(2026, 9, 14, 9, 0, 0) } = {}) {
  const rows = [];
  for (let i = 0; i < 40; i++) {
    rows.push({ created_at: new Date(start + i * 90_000).toISOString(), model: 'example-large', user: `u${i % 7}`, feature: 'chat', usage: { input_tokens: 1800, output_tokens: 350 } });
  }
  const loopStart = start + 20 * 60_000;
  for (let i = 0; i < 600; i++) {
    rows.push({ created_at: new Date(loopStart + i * 2_000).toISOString(), model: 'example-large', user: 'u3', feature: 'agent', run_id: 'run-42', prompt_hash: 'retry-same-tool-call', usage: { input_tokens: 24000 + i * 40, output_tokens: 1200 } });
  }
  return rows;
}

export const EXAMPLE_POLICY = Object.freeze({
  _note: 'Example policy. The prices are placeholders named example-*; put your provider\'s current rates in before relying on any figure.',
  mode: 'enforce',
  prices: {
    'example-large': { in: 3, out: 15, cacheRead: 0.3, cacheWrite: 3.75 },
    'example-small': { in: 0.8, out: 4 },
  },
  requireKnownPrice: true,
  defaultMaxOutputTokens: 1024,
  maxOutputTokens: 8192,
  maxCostPerCallUsd: 0.5,
  budgets: [
    { id: 'org-day', scope: 'global', window: 'day', limitUsd: 25, alertAt: [0.5, 0.8, 1] },
    { id: 'org-month', scope: 'global', window: 'month', limitUsd: 400 },
    { id: 'user-day', scope: 'user', window: 'day', limitUsd: 2 },
    { id: 'run-total', scope: 'run', window: 'total', limitUsd: 3, limitCalls: 150 },
  ],
  breakers: [
    { id: 'loop', scope: 'run', maxRepeats: 20, repeatWindowSec: 300, cooldownSec: 900 },
    { id: 'burst', scope: 'global', maxCallsPerMinute: 120, maxSpendPerMinuteUsd: 2, cooldownSec: 120 },
  ],
});

